command:
set -u; if [ -n "${GITHUB_TOKEN:-}" ]; then echo GITHUB_TOKEN_PRESENT=1; CODE=$(python3 - <<'PY'
import os,urllib.request,urllib.error
t=os.environ.get('GITHUB_TOKEN','')
r=urllib.request.Request('https://api.github.com/repos/gschaidergabriel/frankenstein',headers={'Authorization':'Bearer '+t,'Accept':'application/vnd.github+json','User-Agent':'omega-vps-scope-probe'})
try:
    with urllib.request.urlopen(r,timeout=15) as x: print(x.status)
except urllib.error.HTTPError as e: print(e.code)
except Exception: print('ERR')
PY
); echo FRANKENSTEIN_API_STATUS=$CODE; else echo GITHUB_TOKEN_PRESENT=0; echo FRANKENSTEIN_API_STATUS=NO_TOKEN; fi
